                        if 'k' in castling_rights and c == 4:
                            if board[7][5] == '.' and board[7][6] == '.':
                                if not is_attacked(board, 7, 5, True) and not is_attacked(board, 7, 6, True):
                                    moves.append("e8g8")
                        if 'q' in castling_rights and c == 4:
                            if board[7][4] == '.' and board[7][5] == '.' and board[7][6] == '.':
                                if not is_attacked(board, 7, 5, True) and not is_attacked(board, 7, 4, True):
                                    moves.append("e8d8")
    return moves

def apply_move(board, move):
    from_col = ord(move[0]) - 97
    from_row = 8 - int(move[1])
    to_col = ord(move[2]) - 97
    to_row = 8 - int(move[3])
    new_board = [list(row) for row in board]
    piece = new_board[from_row][from_col]
    new_board[to_row][to_col] = piece
    new_board[from_row][from_col] = '.'

    if len(move) == 5:
        promo_piece = move[4]
        new_board[to_row][to_col] = promo_piece.upper() if piece.isupper() else promo_piece.lower()

    # EP capture logic would require ep_target, omitted for this pass.

    if move == "e1g1": new_board[0][7] = 'R'
    elif move == "e1d1": new_board[0][3] = 'R'
    elif move == "e8g8": new_board[7][7] = 'r'
    elif move == "e8d8": new_board[7][4] = 'r'
    return new_board

def legal_moves(fen: str) -> list[str]:
    board, side, castling, ep = parse_fen(fen)
    pseudo_moves = get_pseudo_moves(board, castling, ep)
    legal = []
    for move in pseudo_moves:
        temp_board = apply_move(board, move)
        if not is_attacked(temp_board, 8-int(move[3]), ord(move[2])-97, side == 'w'):
            legal.append(move)
    return legal

def perft(fen: str, depth: int) -> int:
    if depth == 0:
        return 1
    board, side, castling, ep = parse_fen(fen)
    moves = get_pseudo_moves(board, castling, ep)
    count = 0
    for move in moves:
        new_board = apply_move(board, move)
        new_side = 'b' if side == 'w' else 'w'
        new_fen = "/".join(["".join(row) for row in new_board]) + " " + new_side
        count += perft(new_fen, depth - 1)
    return count
